/** Nama golongan & subgolongan untuk satu kode alat (kode varian memakai kode dasarnya) */
export function alatGroupOf(kode: string): { golongan: string; subgolongan: string } {
  const base = kode.match(/^\d{8}/)?.[0];
  if (!base) return { golongan: 'Lainnya', subgolongan: '' };
  return {
    golongan: ASPAK_ALAT_GOLONGAN[base.slice(1, 3)] || 'Lainnya',
    subgolongan: ASPAK_ALAT_SUBGOLONGAN[base.slice(1, 5)] || '',
  };
}
